mapper.select:
SELECT MEET_ID AS meetId , MEET_TITLE AS meetTitle , DATE_FORMAT(MEET_DT, '%Y-%m-%d') AS meetDt , ATCH_FILE_ID AS atchFileId FROM TB_MEETING WHERE 1=1
AND MEET_DT >= #{searchStartDt}
AND MEET_DT <= #{searchEndDt}
ORDER BY MEET_DT DESC

mapper.insert:
INSERT INTO TB_MEETING (
      MEET_TITLE
    , MEET_DT
    , CONTENT_FULL
    , CONTENT_SUM
    , ACTION_ITEMS
    , LAST_UPDUSR_ID
    , ATCH_FILE_ID
) VALUES (
      #{meetTitle}
    , STR_TO_DATE(#{meetDt}, '%Y-%m-%d')  
    , #{contentFull}
    , #{contentSum}
    , #{actionItems}
    , #{lastUpdusrId}
    , #{atchFileId}
)
